class Solution:
    def isValid(self, s: str) -> bool:
        # pair: 右括号 -> 应与其配对的左括号，统一处理三种括号
        pair = {')': '(', ']': '[', '}': '{'}
        stack = []                       # 栈中保存还未被闭合的左括号
        for ch in s:
            if ch in pair:               # 遇到右括号，必须立刻与最近的左括号配对
                # 栈空说明没有左括号可配；栈顶不匹配说明闭合顺序错误
                if not stack or stack[-1] != pair[ch]:
                    return False
                stack.pop()              # 配对成功，弹出该左括号
            else:                        # 遇到左括号，等待未来的右括号来闭合
                stack.append(ch)
        # 扫描结束后栈必须为空，否则仍有左括号没被闭合
        return not stack

