class Solution {
public:
    bool isValid(string s) {
        // pair: 右括号 -> 应与其配对的左括号，统一处理三种括号
        unordered_map<char, char> pair{{')', '('}, {']', '['}, {'}', '{'}};
        vector<char> stk;                    // 栈中保存尚未被闭合的左括号
        for (char ch : s) {
            auto it = pair.find(ch);
            if (it != pair.end()) {          // 右括号：必须立刻与最近的左括号配对
                // 栈空说明没有左括号可配；栈顶不匹配说明闭合顺序错误
                if (stk.empty() || stk.back() != it->second) return false;
                stk.pop_back();              // 配对成功，弹出该左括号
            } else {
                stk.push_back(ch);           // 左括号：等待未来的右括号来闭合
            }
        }
        // 扫描结束后栈必须为空，否则仍有左括号没被闭合
        return stk.empty();
    }
};

