func isValid(s string) bool {
	pair := map[byte]byte{')': '(', ']': '[', '}': '{'} // 右括号 -> 应配对的左括号
	stack := make([]byte, 0, len(s))                    // 栈中保存尚未被闭合的左括号
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if left, ok := pair[ch]; ok { // 右括号：必须立刻与最近的左括号配对
			// 栈空说明没有左括号可配；栈顶不匹配说明闭合顺序错误
			if len(stack) == 0 || stack[len(stack)-1] != left {
				return false
			}
			stack = stack[:len(stack)-1] // 配对成功，弹出该左括号
		} else {
			stack = append(stack, ch) // 左括号：等待未来的右括号来闭合
		}
	}
	// 扫描结束后栈必须为空，否则仍有左括号没被闭合
	return len(stack) == 0
