class Solution {
public:
    string simplifyPath(string path) {
        vector<string> stk;    // 栈里保存最终保留的每一级目录
        string part;           // 当前正在累积的目录成分（相邻两个 '/' 之间的内容）
        // 手工按 '/' 切分：得到目录名、'.'、'..'，连续斜杠产生的空串直接跳过
        for (int i = 0; i <= (int)path.size(); ++i) {
            if (i < (int)path.size() && path[i] != '/') {
                part += path[i];      // 普通字符累积进当前成分
                continue;
            }
            // 到达分隔符或串尾：结算当前成分
            if (part == "..") {
                if (!stk.empty()) stk.pop_back();  // 回退一级；根目录上保持不变
            } else if (!part.empty() && part != ".") {
                stk.push_back(part);  // '...' 等多个点的名字是合法目录名，正常入栈
            }
            part.clear();
        }
        // 每级目录间恰好一个 '/'，以根 '/' 开头；栈空时结果恰是 '/'
        string ans;
        for (const string& dir : stk) ans += "/" + dir;
        return ans.empty() ? "/" : ans;
    }
};

