class Solution {
    public String simplifyPath(String path) {
        // 按 '/' 切分：得到目录名、'.'、'..'，以及连续斜杠产生的空串
        String[] parts = path.split("/");
        Deque<String> stack = new ArrayDeque<>();   // 栈里保存最终保留的每一级目录
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) continue; // 空串与当前目录跳过
            if (part.equals("..")) {
                if (!stack.isEmpty()) stack.pollLast();   // 回退一级；根目录上保持不变
            } else {
                stack.addLast(part);                      // '...' 等合法目录名正常入栈
            }
        }
        // 每级目录之间恰好一个 '/'，以根 '/' 开头；栈空时结果正是 '/'
        StringBuilder sb = new StringBuilder();
        for (String dir : stack) sb.append('/').append(dir);
        return sb.length() == 0 ? "/" : sb.toString();
    }
}

