class MinStackDiff:
    def __init__(self):
        self.stack = []          # 保存 diff = val - 入栈时刻的最小值
        self.cur_min = None      # 当前栈内最小值（用 None 而非 inf，防首元素 diff 溢出语义）

    def push(self, val: int) -> None:
        if self.cur_min is None:         # 首个元素：它自己就是最小值
            self.cur_min = val
            self.stack.append(0)         # diff = val - val = 0
        else:
            diff = val - self.cur_min
            self.stack.append(diff)
            if diff < 0:                 # diff < 0 说明 val 打破历史最小
                self.cur_min = val

    def pop(self) -> None:
        diff = self.stack.pop()
        if diff < 0:                     # 该层刷新过最小值，还原上一个最小值
            self.cur_min -= diff
        if not self.stack:
            self.cur_min = None          # 栈空复位，避免脏状态

    def top(self) -> int:
        diff = self.stack[-1]
        return self.cur_min if diff < 0 else self.cur_min + diff

    def getMin(self) -> int:
        return self.cur_min

