        # 两栈必须同步弹出，否则辅助栈顶不再对应主栈当前状态
        self.stack.pop()
        self.min_stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        # 辅助栈顶即当前栈内最小值，O(1) 直接读取
        return self.min_stack[-1]

