// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：m（操作次数）
//   接下来 m 行，每行一个操作：
//     push x   —— 将 x 入栈
//     pop      —— 弹出栈顶
//     top      —— 查询栈顶元素
//     getMin   —— 查询栈内最小元素
// 输出格式：每个 top / getMin 操作输出一行结果
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int m;
    cin >> m;
    vector<int> stk, mins;         // 主栈 + 同步辅助栈（栈顶 = 当前最小值）
    while (m--) {
        string op;
        cin >> op;
        if (op == "push") {
            int x;
            cin >> x;
            stk.push_back(x);
            // 新最小值 = min(新元素, 压入前栈内最小值)；每层都必须压
            mins.push_back(mins.empty() ? x : min(x, mins.back()));
        } else if (op == "pop") {
            stk.pop_back();        // 两栈同步弹出
            mins.pop_back();
        } else if (op == "top") {
            cout << stk.back() << "\n";    // 主栈顶即栈顶元素
        } else {                   // getMin
            cout << mins.back() << "\n";   // 辅助栈顶即当前最小值
        }
    }
    return 0;
}

