        stack.push(val);
        // 新最小值 = min(新元素, 压入前栈内最小值)；辅助栈空时就是 val 本身
        int cur = mins.isEmpty() ? val : Math.min(val, mins.peek());
        mins.push(cur);               // 每层都必须压，保证两栈同步
    }

    public void pop() {
        // 两栈必须同步弹出，否则辅助栈顶不再对应当前状态
        stack.pop();
        mins.pop();
    }

    public int top() {
        return stack.peek();          // 主栈顶即栈顶元素
    }

    public int getMin() {
        // 辅助栈顶即当前栈内最小值，O(1) 直接读取
        return mins.peek();
    }
}

