    this.mins.length === 0 ? val : Math.min(val, this.mins[this.mins.length - 1]);
  this.mins.push(cur); // 每层都必须压，保证两栈同步
};

/**
 * @return {void}
 */
MinStack.prototype.pop = function () {
  // 两栈必须同步弹出，否则辅助栈顶不再对应当前状态
  this.stack.pop();
  this.mins.pop();
};

/**
 * @return {number}
 */
MinStack.prototype.top = function () {
  return this.stack[this.stack.length - 1]; // 主栈顶即栈顶元素
};

/**
 * @return {number}
 */
MinStack.prototype.getMin = function () {
  return this.mins[this.mins.length - 1]; // 辅助栈顶即当前最小值
};

