// MinStack：主栈 + 同步辅助栈，push/pop/top/getMin 均为 O(1)
type MinStack struct {
	stack []int // 主栈：存放所有元素
	mins  []int // 辅助栈：与主栈同步，栈顶始终是当前主栈的最小值
}

func Constructor() MinStack {
	return MinStack{}
}

func (this *MinStack) Push(val int) {
	this.stack = append(this.stack, val)
	// 新最小值 = min(新元素, 压入前栈内最小值)；辅助栈空时就是 val 本身
	cur := val
	if len(this.mins) > 0 && this.mins[len(this.mins)-1] < cur {
		cur = this.mins[len(this.mins)-1]
	}
	this.mins = append(this.mins, cur) // 每层都必须压，保证两栈同步
}

func (this *MinStack) Pop() {
	// 两栈必须同步弹出，否则辅助栈顶不再对应当前状态
	this.stack = this.stack[:len(this.stack)-1]
	this.mins = this.mins[:len(this.mins)-1]
}

func (this *MinStack) Top() int {
	return this.stack[len(this.stack)-1] // 主栈顶即栈顶元素
}

func (this *MinStack) GetMin() int {
	// 辅助栈顶即当前栈内最小值，O(1) 直接读取
	return this.mins[len(this.mins)-1]
}

