class Solution {
public:
    int calculate(string s) {
        vector<long long> stk;  // 保存每进入一层括号前的 (累计和, 符号)，交替压栈
        long long result = 0;   // 当前层括号内已经累计的和
        long long sign = 1;     // 下一个数字的符号：1 为正，-1 为负
        long long num = 0;      // 正在读取的（多位）数字
        for (char ch : s) {
            if (isdigit(ch)) {
                num = num * 10 + (ch - '0');   // 多位数累积
            } else if (ch == '+') {
                result += sign * num;          // 结算上一个数，随后准备正号
                num = 0; sign = 1;
            } else if (ch == '-') {
                result += sign * num;          // 结算上一个数；一元负号也走这里
                num = 0; sign = -1;
            } else if (ch == '(') {
                // 进入新一层括号：保存当前层的累计和与符号，从零开始算括号内
                stk.push_back(result);
                stk.push_back(sign);
                result = 0; sign = 1; num = 0;
            } else if (ch == ')') {
                result += sign * num;          // 结算括号内最后一个数
