class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        // 末尾加一根高度 0 的哨兵柱，保证遍历结束时所有柱子都被弹栈结算
        heights.push_back(0);
        vector<int> stk;     // 栈底哨兵：默认左边界为 -1；栈存下标且对应高度递增
        stk.push_back(-1);
        int ans = 0;
        for (int i = 0; i < (int)heights.size(); ++i) {
            // 当前柱比栈顶矮 -> 栈顶柱的左右边界都已确定，立即结算它
            while (stk.back() != -1 && heights[stk.back()] >= heights[i]) {
                int height = heights[stk.back()]; stk.pop_back();
                // 宽度 = 右边界 i 与左边界 stk.back() 之间的柱子数（不含两端）
                int width = i - stk.back() - 1;
                ans = max(ans, height * width);
            }
            stk.push_back(i);   // 当前柱入栈，等待未来更矮的柱子来结算它
        }
        heights.pop_back();     // 弹出补进去的哨兵柱，还原输入数组
        return ans;
    }
};

